"""Generate the IBM Plex Mono bitmap subset (requires Pillow)."""
import argparse
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("font", type=Path, help="IBM Plex Mono Regular TTF")
args = parser.parse_args()
root = Path(__file__).resolve().parents[2]
out = [
    '// IBM Plex Mono bitmap subset, SIL Open Font License; see tools/ui/OFL-IBMPlexMono.txt.',
    '// Generated by tools/ui/font.py.',
    '#ifndef UI_FONT_H',
    '#define UI_FONT_H',
    '#include <stdint.h>',
    'typedef struct { uint16_t offset; uint8_t width, advance; } UiGlyph;',
    'typedef struct { const UiGlyph *glyphs; const uint8_t *pixels; uint8_t height; } UiFont;',
]
for size in (10, 11):
    font = ImageFont.truetype(str(args.font), size)
    advance = round(font.getlength('M'))
    data, glyphs = [], []
    for code in range(32, 127):
        width, height = advance, size + 4
        im = Image.new('L', (width, height))
        ImageDraw.Draw(im).text((0, size), chr(code), font=font, fill=255, anchor='ls')
        glyphs.append((len(data), width, advance))
        for y in range(height):
            for x in range(0, width, 4):
                data.append(sum(
                    round(im.getpixel((xx, y)) * 3 / 255) << ((xx - x) * 2)
                    for xx in range(x, min(x + 4, width))
                ))
    out.append(f'static const UiGlyph ui_glyphs_{size}[] = {{')
    out.extend('    {%d, %d, %d},' % g for g in glyphs)
    out.append('};')
    out.append(f'static const uint8_t ui_pixels_{size}[] = {{')
    out.extend(
        '    ' + ', '.join(f'0x{v:02x}' for v in data[i:i + 24]) + ','
        for i in range(0, len(data), 24)
    )
    out.append('};')
    out.append(f'static const UiFont ui_font_{size} = {{ui_glyphs_{size}, ui_pixels_{size}, {size + 4}}};')
out.extend(['#endif', ''])
(root / 'arm9/include/ui_font.h').write_text('\n'.join(out))
